div.script:
/*------------ POPUP ------------- */
if (typeof universal_popup === 'undefined') {

    function universal_popup() {
        let btn = document.querySelectorAll('.btn-universal_popup');
        let overlay = document.querySelector('.universal_popup-overlay');
        let body = document.querySelector('body');
        let universal_popup = null;
        let close = null;
        let _this = this;


        if (!btn || btn.length === 0 || !overlay || !body) {
            return;
        }


        let imp_conts = document.querySelectorAll('.universal_popup-overlay');
        if(imp_conts.length > 1){
            let imp_cont = document.body.appendChild(imp_conts[0])
            for(let i=0; i < imp_conts.length; i++)
                imp_conts[i].remove()
            document.body.appendChild(imp_cont)
        }

        for (var i = 0; i < btn.length; i++) {
            btn[i].addEventListener('click', function(e) {
                e.preventDefault();

                const popupAttr = this.getAttribute('data-universal_popup');
                if (!popupAttr) {
                    //console.warn('Missing data-universal_popup attribute');
                    return;
                }

                universal_popup = document.querySelector('.universal_popup-' + popupAttr);

                if (!universal_popup) {
                    //console.warn('Universal popup not found');
                    return;
                }

                close = universal_popup.querySelectorAll('.universal_popup-close');
                let top = window.pageYOffset || document.documentElement.scrollTop;
                let left = window.pageXOffset || document.documentElement.scrollLeft;

                overlay.classList.add('active');
                body.classList.add('body_no_overflow');
                universal_popup.classList.add('active');
                universal_popup.style.top = (top + 100) + 'px';

                if (close && close.length > 0) {
                    close.forEach(closeBtn => {
                        if (typeof closeBtn.addEventListener === 'function') {
                            closeBtn.addEventListener('click', closePopup);
                        }
                    });
                }

                if (typeof overlay.addEventListener === 'function') {
                    overlay.addEventListener('click', closePopup);
                }

                const popupBody = universal_popup.querySelector('.body');
                if (popupBody && typeof popupBody.scrollTo === 'function') {
                    popupBody.scrollTo({ top: 0 });
                }
            });
        }

        document.addEventListener('keydown', function(e) {
            if (e.keyCode == 27) {
                if (typeof closePopup === 'function') {
                    closePopup(e);
                }
            }
        });

        function closePopup(e) {
            e.preventDefault();

            if (!overlay || !body) {
                return;
            }

            if (overlay.classList && typeof overlay.classList.remove === 'function') {
                overlay.classList.remove('active');
            }

            if (universal_popup && universal_popup.classList && typeof universal_popup.classList.remove === 'function') {
                universal_popup.classList.remove('active');
            }

            if (body.classList && typeof body.classList.remove === 'function') {
                body.classList.remove('body_no_overflow');
            }
        }

        function univPopScroll() {
            const buttons = document.querySelectorAll('.btn-universal_popup');
            if (!buttons || buttons.length === 0) {
                return;
            }

            buttons.forEach(link => {
                link.onclick = (event) => {
                    event.preventDefault();

                    // Check if dataset.anchor exists
                    if (!event.target || !event.target.dataset || !event.target.dataset.anchor) {
                        //console.warn('Missing data-anchor attribute');
                    }
                    const anchor = document.getElementById('treatment' + event.target.dataset.anchor);
                    if (!anchor) {
                        //console.warn('Anchor element not found');
                        return;
                    }

                    const imp_pop = anchor.closest('.universal_popup');
                    if (!imp_pop) {
                        //console.warn('Universal popup container not found');
                        return;
                    }

                    const head = imp_pop.querySelector('.head');
                    const body = imp_pop.querySelector('.body');

                    if (!body) {
                        //console.warn('Popup body not found');
                        return;
                    }

                    // Scroll body to top
                    if (typeof setTimeout === 'function') {
                        setTimeout(() => {
                            if (body && typeof body.scrollTo === 'function') {
                                body.scrollTo({top: 0});
                            }
                        }, 50);

                        // Scroll to anchor position
                        setTimeout(() => {
                            if (!link.dataset || !link.dataset.anchor) {
                                return;
                            }

                            const targetAnchor = document.getElementById('treatment' + link.dataset.anchor);

                            if (targetAnchor && body && typeof body.scrollTo === 'function') {
                                if (typeof targetAnchor.getBoundingClientRect === 'function') {
                                    const pos           = targetAnchor.getBoundingClientRect();
                                    const styleBody     = window.getComputedStyle(body);
                                    const paddingBody   = parseFloat(styleBody.getPropertyValue('padding-top')) || 0;
                                    const offSetValDT   = 50;
                                    const offSetValMOB  = 20;

                                    let positionScroll = 0;

                                    if (window.innerWidth < 600) {
                                        const headHeight = head ? head.offsetHeight : 0;
                                        positionScroll = (pos.top - paddingBody) - headHeight - offSetValMOB;
                                    } else {
                                        const headHeight = head ? head.offsetHeight : 0;
                                        positionScroll = (pos.top - paddingBody) - headHeight - (targetAnchor.offsetHeight + offSetValDT);
                                    }

                                    body.scrollTo({
                                        top: positionScroll,
                                        behavior: 'smooth'
                                    });
                                }
                            }
                        }, 100);
                    }
                }
            });
        }

        if (typeof univPopScroll === 'function') {
            univPopScroll();
        }
    }

    if (typeof universal_popup === 'function') {
        universal_popup();
    }
}

document.addEventListener('DOMContentLoaded', (event) => {

    (function() {

        const isiLinks = document.querySelectorAll('.toc li a');
        const isiPop = document.querySelector('.universal_popup');

        // Early return if no links found
        if (!isiLinks || isiLinks.length === 0) {
            return;
        }

        if (isiPop) {

            const body = isiPop.querySelector('.inner .body');
            const head = isiPop.querySelector('.head');

            // Only proceed if both body and head exist
            if (!body) {
                //console.warn('Popup body element not found');
                return;
            }

            isiLinks.forEach(link => {
                link.onclick = (event) => {
                    event.preventDefault();

                    // Check if target and dataset exist
                    if (!event.target || !event.target.dataset || !event.target.dataset.anchor) {
                        //console.warn('Missing anchor data attribute');
                        return;
                    }

                    const anchorId = event.target.dataset.anchor;
                    const anchor = document.getElementById(anchorId);
                    if (!anchor) {
                        //console.warn(`Anchor element not found: ${anchorId}`);
                        return;
                    }

                    // Reset scroll position
                    if (typeof body.scrollTo === 'function') {
                        body.scrollTo({ top: 0 });
                    }

                    // Calculate position with fallback for head
                    const headHeight = head ? head.offsetHeight : 0;
                    const positionScroll = anchor.offsetTop - headHeight;

                    if (typeof body.scrollTo === 'function') {
                        body.scrollTo({
                            top: positionScroll,
                            behavior: 'smooth'
                        });
                    }
                };
            });
        }

        else {

            isiLinks.forEach(link => {
                link.onclick = (event) => {
                    event.preventDefault();

                    // Check if target and dataset exist
                    if (!event.target || !event.target.dataset || !event.target.dataset.anchor) {
                        //console.warn('Missing anchor data attribute');
                        return;
                    }

                    const anchorId = 'treatment' + event.target.dataset.anchor;

                    const anchor = document.getElementById(anchorId);

                    if (!anchor) {
                        //console.warn(`Anchor element not found: ${anchorId}`);
                        return;
                    }

                    const positionScroll = anchor.offsetTop - 20;

                    if (typeof window.scrollTo === 'function') {
                        window.scrollTo({
                            top: positionScroll,
                            behavior: 'smooth'
                        });
                    }
                };
            });

        }

    })();

});

    const aos = () => {
		AOS.init({
          offset: 200,
          duration: 600,
          easing: 'ease-in-sine',
          delay: 100,
          once: true    
        });
    }

    const lottie_img_hover = (lottie_target = '/assets/img/lottie/') => {
        const icons = document.querySelectorAll('.hover-icon i');
        const animations = new Map(); 

        icons.forEach(icon => {
            const animation = lottie.loadAnimation({
                container: icon,
                path: lottie_target + icon.dataset.src + '.json',
                renderer: icon.dataset.render || 'svg',
                loop: false,
                autoplay: false, 
            });

            animations.set(icon, animation);

            animation.addEventListener('complete', () => {
                icon.dataset.start = 'true';
            });
        });

        icons.forEach(icon => {
            const parent = icon.closest('.hover-icon');
            const animation = animations.get(icon);

            const start = () => {
                if (icon.dataset.start !== 'false') {
                    icon.dataset.start = 'false';
                    animation.stop();   
                    animation.play();   
                }
            };

            parent.addEventListener('mouseover', start);
            parent.addEventListener('touchstart', start, { passive: true });
        });
    };

    const lottie_img = (lottie_target = '/assets/img/lottie/') => {
        let icons = document.querySelectorAll('.icon-svg');

        const isFullyVisible = (el)=>{
            let elementBoundary = el.getBoundingClientRect();

            let top = elementBoundary.top;
            let bottom = elementBoundary.bottom;

            return ((top >= 0) && (bottom <= window.innerHeight));
        }

        const scrolling = () => {
            icons.forEach(icon => {
                if (isFullyVisible(icon)) {
                    if (icon.dataset.start == 'true') {                 
                        lottie.loadAnimation({
                            container: icon,
                            path: lottie_target + icon.dataset.src + '.json',
                            renderer: icon.dataset.render,
                            loop: (icon.dataset.loop) ? true : false,
                            autoplay: true
                        });

                        icon.dataset.start = false;
                    }                
                }
            }); 
        }

        document.addEventListener('scroll', scrolling);
        document.addEventListener('DOMContentLoaded', scrolling);
    }

    /* ANCHOR */ 
    const anchor_animation = () => {
        let anchors = document.querySelectorAll('a[href*="#"]')
        anchors.forEach(anchor => {

            if(anchor.attributes[0].nodeValue.indexOf('?') === -1){
                anchor.addEventListener('click', (e) => {
                    e.preventDefault()

                    let blockID = anchor.getAttribute('href').substr(1)
                    let element = document.getElementById(blockID) 

                    if (element != null) {
                        let pos = (element.getBoundingClientRect().top + window.pageYOffset)
                        pos = pos + 5
                        window.scrollTo({top: pos, behavior: 'smooth'})
                    }           
                })
            }
        })
    }


    /* SHOW FIXED BTN */
    const showBtnFixed = (target_class, scroll_element_class) => {
        const target        = document.querySelector(target_class)
        const scroll_target = document.querySelector(scroll_element_class)
        if(!target || !scroll_target) return

        const pos           = scroll_target.offsetTop - window.innerHeight + 185
        window.addEventListener('scroll', () => {
            if (window.scrollY >= pos && window.innerWidth <= 750)
                target.classList.add('show');
            else
                target.classList.remove('show');
        })
    }

    /* ANIMATION SCROLL PAGE
    ---------------------------------------------------- */
    const animationScrollPage = () => {
        let isScrolling = false;


        let throttleScroll = (e) => {
            if (isScrolling == false) {
                window.requestAnimationFrame(function() {
                    scrolling(e);
                    isScrolling = false;
                });
            }

            isScrolling = true;
        }

        let animation = document.querySelectorAll('.an');

        let scrolling = (e) => {
            if (animation.length) {
                for (let i = 0; i < animation.length; i++) {
                    if (isPartiallyVisible(animation[i])) {
                        animation[i].classList.add("an-no"); 
                    } else {
                        animation[i].classList.remove("an-no"); 
                    }
                }
            }
        }

        let isPartiallyVisible = (el) => {
            let elementBoundary = el.getBoundingClientRect();

            let top = elementBoundary.top;
            let bottom = elementBoundary.bottom;
            let height = elementBoundary.height;

            return ((top + height >= 0) && (height + window.innerHeight >= bottom));
        }

        let isFullyVisible = (el) => {
            let elementBoundary = el.getBoundingClientRect();

            let top = elementBoundary.top;
            let bottom = elementBoundary.bottom;

            return ((top >= 0) && (bottom <= window.innerHeight));
        }

        window.addEventListener("scroll", throttleScroll, false);
        document.addEventListener("DOMContentLoaded", scrolling, false);
    }

    /* ANIMATION PAGE
    ---------------------------------------------------- */
    const animScrollPage =  () => {
        const elems = document.querySelectorAll('.animated');
        const options = {rootMargin: '0px'}

        const observer = new IntersectionObserver(entries => {
            entries.forEach(entry => {
                if (entry.isIntersecting)
                    entry.target.classList.add('show');
            });
        }, options);

        elems.forEach(elem => {
            observer.observe(elem);
        });
    }

    const scrollHomeParallax = (selector) => {
        const scroll = document.querySelector(selector)

        window.addEventListener('scroll', () => scroll.style.backgroundPositionY = window.scrollY / 2 + 'px')
    }

    const fixedSnippet = (e,t) => {
        let lastScrollTop = 0;

        window.addEventListener('scroll', () => {
            const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
            const fixedRight = e
            const home = t

            if (window.scrollY > home.offsetHeight) fixedRight.classList.add('active');
            else fixedRight.classList.remove('active');
        });
    }

    const accordeon = () => {
        let btnAccord   =   document.querySelectorAll('.btn-accordeon');

        btnAccord.forEach(b => {
            b.addEventListener('click', () => {
                let items       = document.querySelectorAll('.item-accordeon')
                let contents    = document.querySelectorAll('.content-accordeon')
                let inner       = b.parentNode.querySelector('.inner')
                let content     = b.parentNode.querySelector('.content-accordeon')

                items.forEach(i =>i.classList.remove('active'))
                contents.forEach(c => c.removeAttribute('style'))
                b.parentNode.classList.add('active')
                content.style.height = inner.clientHeight + 'px'
            })
        })
    }


    const accordion = () => {
        let btns = document.querySelectorAll('.accordion_item_slide_toggle')

        btns.forEach(b => {
            b.onclick = () => {
                if(b.nextElementSibling.style.display && b.nextElementSibling.style.display == 'block') return $(b.nextElementSibling).slideUp(200)
                btns.forEach(r => {
                    r.classList.remove('open')
                    $(r.nextElementSibling).slideUp(200)
                })
                $(b.nextElementSibling).slideToggle(200)
            }
        });
    }

    const accordion2 = () => {
        let btns = document.querySelectorAll('.accordion__head')

        btns.forEach(b => {
            b.onclick = () => {
                btns.forEach(r => {
                    r.classList.remove('open')
                    $(r.nextElementSibling).slideUp(200)
                })
                $(b.nextElementSibling).slideToggle(200)
            }
        });
    }


    /* ACCORDEON
    ------------------------------------ */
    function accordion_toggle() {
        let accordeon = document.querySelectorAll('.accordeon');
        let flag = true;

        if (accordeon != null) {
            for (let i = 0; i < accordeon.length; i++) {
                item = accordeon[i].querySelectorAll('.item-accordeon');

                for (let j = 0; j < item.length; j++) {
                    if (item[j].classList.contains('active')) {
                        let inner = item[j].querySelector('.inner');
                        let content = item[j].querySelector('.content-accordeon'); 
                        content.style.height = (inner.clientHeight + 2) + 'px';
                    }

                    let btn = item[j].querySelector('.btn-accordeon');

                    btn.addEventListener('click', openAccordeon);
                }
            }
        }

        function openAccordeon(e) {
            let item = this.closest('.accordeon').querySelectorAll('.item-accordeon');
            let inner = this.parentNode.querySelector('.inner');
            let content = this.parentNode.querySelector('.content-accordeon');  

            if (this.parentNode.classList.contains('active')) {            
                this.parentNode.classList.remove('active');
                content.removeAttribute('style');
            } else {   
                this.parentNode.classList.add('active');
                content.style.height = (inner.clientHeight + 2) + 'px';
            }    
        }
    }

    /* DOTS
    ---------------------------------------------------- */
    const anim_dots = (id, color = '#24326', dotSize = 4, distance = 20) => {
        let t = document.getElementById(id);
        if(!t) return;

        let stageWidth;
        let stageHeight;

        let ctx = t.getContext('2d');
        let objectList;
        let timeout;
        let smallDotSize = 1;
        let bigDotSize = dotSize;
        let prms = {
            fps: 6, // speed
            objectDistance: distance, // distance between each dot
            objectWidth: dotSize, // radius/size of the dots
            objectRotationV: Math.PI * .09,
            objectRadius: 0 // spiral level; keep 0 to get a circle
        };

        let xAngle = 25;
        let yAngle = 65;

        let onEnterFrame = () => {
            let len = objectList.length
            let object
            while (len > 0) {
                len -= 1
                object = objectList[len]
                object.tick()
            }
            ctx.clearRect(0, 0, stageWidth, stageHeight)
            ctx.fillStyle = color
            len = objectList.length
            while (len > 0) {
                len -= 1
                object = objectList[len]
                object.draw(ctx)
            }

            timeout = setTimeout(onEnterFrame, 1000 / prms.fps);
        }

        let reset = ()=> {

            stageWidth = t.parentElement.offsetWidth
            stageHeight = t.parentElement.offsetHeight

            t.setAttribute('width', stageWidth)
            t.setAttribute('height', stageHeight)

            // Create display object
            objectList = []
            let x = 4 // -prms.objectDistance * .5;
            let y = 4
            while (x < stageWidth + prms.objectDistance * .5) {
                y = 4; // -prms.objectDistance * .5;
                while (y < stageHeight + prms.objectDistance * .5) {
                        let xDistance = x - stageWidth * xAngle
                        let yDistance = y - stageHeight * yAngle
                        let distance = Math.sqrt(xDistance * xDistance + yDistance * yDistance)
                        let circleRotation = Math.PI * .005 * distance
                        objectList.push(new Circle(x, y, circleRotation // _rotationV
                        ));
                        y += prms.objectDistance
                    }
                    x += prms.objectDistance
                }

            // Reset timer
            if (timeout)
                clearTimeout(timeout);

            timeout = setTimeout(onEnterFrame, 1000 / prms.fps)
         }

        window.onresize = ()=> reset()
        reset();

        function Circle(_x, _y, _rotation) {
            this.x = _x;
            this.y = _y;
            this.vx = 0;
            this.vy = 0;
            this.ax = 0;
            this.ay = 0;
            this.rotation = _rotation;
            this.cx = _x;
            this.cy = _y;
        }

        Circle.prototype.width = prms.objectWidth
        Circle.prototype.rotationV = prms.objectRotationV
        Circle.prototype.radius = prms.objectRadius
        Circle.prototype.tick = function() {
            this.rotation += this.rotationV
            this.x = this.radius * Math.cos(this.rotation) + this.cx
            this.y = this.radius * Math.sin(this.rotation) + this.cy
            this.width = (smallDotSize + Math.cos(this.rotation)) * Circle.prototype.width
        }

        Circle.prototype.draw = function(_context) {
            _context.beginPath()
            _context.arc(this.x, this.y, this.width * .4, 0, Math.PI * 2, false)
            _context.fill()
            _context.closePath()
        }
    }

    /* TYPER NUMBER
    ---------------------------------------------------- */
    function typerNumber() {
        const typerAll = document.querySelectorAll('.typer-number');
        const options = {rootMargin: '0px'}

        const observer = new IntersectionObserver(entries => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    if (!entry.target.classList.contains('finish')) {
                        const numberList = entry.target.querySelectorAll('span');

                        numberList.forEach(number => {
                            let min = Number(number.dataset.min);
                            let max = Number(number.dataset.max);
                            let time = Number(number.dataset.time);
                            let delay = Number(number.dataset.delay);

                            setTimeout(() => {
                                let interval = setInterval(() => {
                                    if (number.dataset.reverse) {
                                        max -= 1;
                                        number.textContent = max;
                                        if (max <= min) {
                                            entry.target.classList.add('finish');
                                            clearInterval(interval);
                                        } 
                                    } else {
                                        min += 1;
                                        number.textContent = min;
                                        if (min >= max) {
                                            entry.target.classList.add('finish');
                                            clearInterval(interval);
                                        } 
                                    }
                                }, time);
                            }, delay);
                        });
                    }
                }
            });
        }, options);

        typerAll.forEach(elem => {
            observer.observe(elem);
        });
    }

/*------------ POPUP ------------- */
if (typeof universal_popup === 'undefined') {

    function universal_popup() {
        let btn = document.querySelectorAll('.btn-universal_popup');
        let overlay = document.querySelector('.universal_popup-overlay');
        let body = document.querySelector('body');
        let universal_popup = null;
        let close = null;
        let _this = this;


        if (!btn || btn.length === 0 || !overlay || !body) {
            return;
        }


        let imp_conts = document.querySelectorAll('.universal_popup-overlay');
        if(imp_conts.length > 1){
            let imp_cont = document.body.appendChild(imp_conts[0])
            for(let i=0; i < imp_conts.length; i++)
                imp_conts[i].remove()
            document.body.appendChild(imp_cont)
        }

        for (var i = 0; i < btn.length; i++) {
            btn[i].addEventListener('click', function(e) {
                e.preventDefault();

                const popupAttr = this.getAttribute('data-universal_popup');
                if (!popupAttr) {
                    //console.warn('Missing data-universal_popup attribute');
                    return;
                }

                universal_popup = document.querySelector('.universal_popup-' + popupAttr);

                if (!universal_popup) {
                    //console.warn('Universal popup not found');
                    return;
                }

                close = universal_popup.querySelectorAll('.universal_popup-close');
                let top = window.pageYOffset || document.documentElement.scrollTop;
                let left = window.pageXOffset || document.documentElement.scrollLeft;

                overlay.classList.add('active');
                body.classList.add('body_no_overflow');
                universal_popup.classList.add('active');
                universal_popup.style.top = (top + 100) + 'px';

                if (close && close.length > 0) {
                    close.forEach(closeBtn => {
                        if (typeof closeBtn.addEventListener === 'function') {
                            closeBtn.addEventListener('click', closePopup);
                        }
                    });
                }

                if (typeof overlay.addEventListener === 'function') {
                    overlay.addEventListener('click', closePopup);
                }

                const popupBody = universal_popup.querySelector('.body');
                if (popupBody && typeof popupBody.scrollTo === 'function') {
                    popupBody.scrollTo({ top: 0 });
                }
            });
        }

        document.addEventListener('keydown', function(e) {
            if (e.keyCode == 27) {
                if (typeof closePopup === 'function') {
                    closePopup(e);
                }
            }
        });

        function closePopup(e) {
            e.preventDefault();

            if (!overlay || !body) {
                return;
            }

            if (overlay.classList && typeof overlay.classList.remove === 'function') {
                overlay.classList.remove('active');
            }

            if (universal_popup && universal_popup.classList && typeof universal_popup.classList.remove === 'function') {
                universal_popup.classList.remove('active');
            }

            if (body.classList && typeof body.classList.remove === 'function') {
                body.classList.remove('body_no_overflow');
            }
        }

        function univPopScroll() {
            const buttons = document.querySelectorAll('.btn-universal_popup');
            if (!buttons || buttons.length === 0) {
                return;
            }

            buttons.forEach(link => {
                link.onclick = (event) => {
                    event.preventDefault();

                    // Check if dataset.anchor exists
                    if (!event.target || !event.target.dataset || !event.target.dataset.anchor) {
                        //console.warn('Missing data-anchor attribute');
                    }
                    const anchor = document.getElementById('treatment' + event.target.dataset.anchor);
                    if (!anchor) {
                        //console.warn('Anchor element not found');
                        return;
                    }

                    const imp_pop = anchor.closest('.universal_popup');
                    if (!imp_pop) {
                        //console.warn('Universal popup container not found');
                        return;
                    }

                    const head = imp_pop.querySelector('.head');
                    const body = imp_pop.querySelector('.body');

                    if (!body) {
                        //console.warn('Popup body not found');
                        return;
                    }

                    // Scroll body to top
                    if (typeof setTimeout === 'function') {
                        setTimeout(() => {
                            if (body && typeof body.scrollTo === 'function') {
                                body.scrollTo({top: 0});
                            }
                        }, 50);

                        // Scroll to anchor position
                        setTimeout(() => {
                            if (!link.dataset || !link.dataset.anchor) {
                                return;
                            }

                            const targetAnchor = document.getElementById('treatment' + link.dataset.anchor);

                            if (targetAnchor && body && typeof body.scrollTo === 'function') {
                                if (typeof targetAnchor.getBoundingClientRect === 'function') {
                                    const pos           = targetAnchor.getBoundingClientRect();
                                    const styleBody     = window.getComputedStyle(body);
                                    const paddingBody   = parseFloat(styleBody.getPropertyValue('padding-top')) || 0;
                                    const offSetValDT   = 50;
                                    const offSetValMOB  = 20;

                                    let positionScroll = 0;

                                    if (window.innerWidth < 600) {
                                        const headHeight = head ? head.offsetHeight : 0;
                                        positionScroll = (pos.top - paddingBody) - headHeight - offSetValMOB;
                                    } else {
                                        const headHeight = head ? head.offsetHeight : 0;
                                        positionScroll = (pos.top - paddingBody) - headHeight - (targetAnchor.offsetHeight + offSetValDT);
                                    }

                                    body.scrollTo({
                                        top: positionScroll,
                                        behavior: 'smooth'
                                    });
                                }
                            }
                        }, 100);
                    }
                }
            });
        }

        if (typeof univPopScroll === 'function') {
            univPopScroll();
        }
    }

    if (typeof universal_popup === 'function') {
        universal_popup();
    }
}

document.addEventListener('DOMContentLoaded', (event) => {

    (function() {

        const isiLinks = document.querySelectorAll('.toc li a');
        const isiPop = document.querySelector('.universal_popup');

        // Early return if no links found
        if (!isiLinks || isiLinks.length === 0) {
            return;
        }

        if (isiPop) {

            const body = isiPop.querySelector('.inner .body');
            const head = isiPop.querySelector('.head');

            // Only proceed if both body and head exist
            if (!body) {
                //console.warn('Popup body element not found');
                return;
            }

            isiLinks.forEach(link => {
                link.onclick = (event) => {
                    event.preventDefault();

                    // Check if target and dataset exist
                    if (!event.target || !event.target.dataset || !event.target.dataset.anchor) {
                        //console.warn('Missing anchor data attribute');
                        return;
                    }

                    const anchorId = event.target.dataset.anchor;
                    const anchor = document.getElementById(anchorId);
                    if (!anchor) {
                        //console.warn(`Anchor element not found: ${anchorId}`);
                        return;
                    }

                    // Reset scroll position
                    if (typeof body.scrollTo === 'function') {
                        body.scrollTo({ top: 0 });
                    }

                    // Calculate position with fallback for head
                    const headHeight = head ? head.offsetHeight : 0;
                    const positionScroll = anchor.offsetTop - headHeight;

                    if (typeof body.scrollTo === 'function') {
                        body.scrollTo({
                            top: positionScroll,
                            behavior: 'smooth'
                        });
                    }
                };
            });
        }

        else {

            isiLinks.forEach(link => {
                link.onclick = (event) => {
                    event.preventDefault();

                    // Check if target and dataset exist
                    if (!event.target || !event.target.dataset || !event.target.dataset.anchor) {
                        //console.warn('Missing anchor data attribute');
                        return;
                    }

                    const anchorId = 'treatment' + event.target.dataset.anchor;

                    const anchor = document.getElementById(anchorId);

                    if (!anchor) {
                        //console.warn(`Anchor element not found: ${anchorId}`);
                        return;
                    }

                    const positionScroll = anchor.offsetTop - 20;

                    if (typeof window.scrollTo === 'function') {
                        window.scrollTo({
                            top: positionScroll,
                            behavior: 'smooth'
                        });
                    }
                };
            });

        }

    })();

});
